INSERT INTO `sms_templates` (`id`, `name`, `content`, `slug`, `active`, `created_at`, `updated_at`, `deleted_at`, `account_id`) VALUES
(1, 'On consultancy appointment SMS', 'Dear ##patient_name##, you have booked an appointment with ##doctor_name## at Smart Aesthetics.\n\nDate: ##appointment_date##\nTime: ##appointment_time##\nAddress: ##centre_address##\nMap Directions: ##centre_google_map##', 'on-appointment', 0, '2019-01-10 10:44:01', '2022-08-04 06:13:41', NULL, 1),
(2, '2nd message one day before consultancy appointment at 8PM', 'Dear ##patient_name##, its a reminder for your appointment with ##doctor_name## at ##appointment_time##, tomorrow.\r\n\r\nDirections: ##centre_google_map##\r\n\r\nFor any changes, please contact ##fdo_phone##', 'second-sms', 0, '2019-01-10 10:44:01', '2022-06-27 12:19:54', NULL, 1),
(3, '3rd reminder 2 hours before consultancy appointment', 'Reminder: Dear ##patient_name##, you have an appointment with ##doctor_name## today at ##appointment_time##.\r\n\r\nFor any guidance, call ##fdo_phone##', 'third-sms', 0, '2019-01-10 10:44:01', '2022-06-27 12:19:55', NULL, 1),
(4, 'Promotion SMS', 'Smart Aesthetics has been endorsed by Pakistan\'s top celebrities and Blogs:\nNadia Khan: https://youtu.be/l8IaZcvxd9Y\nAadi Adeal: https://youtu.be/IAgFVrRNwUw\nNida Yasir: https://youtu.be/PryOYqoj4O8\nTribune: https://bit.ly/2rBAp4X', 'promotion-sms', 0, '2019-01-10 10:44:01', '2019-01-10 14:08:33', NULL, 1),
(5, 'On treatment appointment SMS', 'Dear ##patient_name##, you have booked your treatment with Smart on ##appointment_date## at ##appointment_time##\n\nFor any queries, contact ##fdo_phone##', 'treatment-on-appointment', 0, '2019-02-07 14:19:11', '2022-06-27 12:19:57', NULL, 1),
(6, '2nd message one day before treatment appointment at 8PM', 'Reminder: Hey ##patient_name##, your treatment is scheduled with Smart at ##appointment_time##, tomorrow.\n\nFor any queries, call ##fdo_phone##', 'treatment-second-sms', 0, '2019-02-07 14:19:11', '2022-06-27 12:19:59', NULL, 1),
(7, '3rd reminder 2 hours before treatment appointment', 'Reminder: Hey ##patient_name##, your treatment is scheduled with Smart at ##appointment_time##, today.\n\nFor any queries, call ##fdo_phone##', 'treatment-third-sms', 0, '2019-02-07 14:19:11', '2021-02-23 09:44:37', NULL, 1),
(8, 'On Invoice Ringup SMS', 'Dear ##patient_name## , you have taken ##service_name## at Smart Aesthetics on ##created_at##. Your remaining balance is ##remaining_balance##. Thank you for your business with Smart Aesthetics.', 'invoice-ringup', 0, '2020-07-06 07:42:33', '2020-07-06 12:44:18', NULL, 1),
(9, 'On Plan Cah Received SMS', 'Dear ##patient_name##, we received a payment of Rs.##cash_amount## on ##created_at## against Plan ##id##. Thank you for your business.', 'plan-cash', 0, '2020-07-06 07:42:33', '2022-06-27 12:20:01', NULL, 1),
(10, 'On Refund SMS', 'Dear ##patient_name##, Smart Aesthetics has processed a refund of ##cash_amount## on ##created_at##. Thank you for your business with Smart Aesthetics.', 'refund-amount', 0, '2020-07-06 07:42:33', '2020-07-06 12:44:52', NULL, 1),
(11, 'On virtual consultancy appointment SMS', 'Dear ##patient_name##, you have booked a consultation with Smart Aesthetics. Your appointment details are;\n\nType: Virtual consultation\nConsultant: ##doctor_name##\nDate: ##appointment_date##\nTime: ##appointment_time##\n\nFor any queries, please call ##fdo_phone##', 'virtual-on-appointment', 0, '2020-09-16 15:20:03', '2022-06-27 12:20:03', NULL, 1),
(12, '2nd message one day before virtual consultancy appointment at 8PM', 'Hi ##patient_name##, it\'s a reminder that you have an appointment with ##doctor_name## at ##appointment_time##, tomorrow, ##appointment_date##\n\nAddress: ##centre_address##\nDirections: ##centre_google_map##\n\nFor any queries, call ##head_office_phone##', 'virtual-second-sms', 0, '2020-09-16 15:20:03', '2021-04-06 16:22:09', NULL, 1),
(13, '3rd reminder 2 hours before virtual consultancy appointment', 'Reminder: Dear ##patient_name##, you have a virtual consultation scheduled with ##doctor_name## at ##appointment_time##, today.', 'virtual-third-sms', 0, '2020-09-16 15:20:03', '2022-03-29 13:12:12', NULL, 1);
